import { useEffect, useState } from "react";
import SideBar from "../components/UI/SuitabilitySidebar";
import MapComponent from "../components/Data-Display/Map";
import SliderComponent from "../components/Data-Display/sliderpage";
import SidebysideComponent from "../components/Data-Display/Sidebyside";
import "../styles/SuitabilityMap.css";
import SuitabilityDetailPopup from "../components/Popups/Suitabilitydetailpopup";


function SuitabilityMap() {
    const [isSidebarOpen, setIsSidebarOpen] = useState(() => window.innerWidth > 768);
    const [geoJsonKey, setGeoJsonKey] = useState(0);
    const [suitabilityLayers, setSuitabilityLayers] = useState({
        "Highly Suitable": true,
        "Moderately Suitable": true,
        "Marginally Suitable": true,
        "Not Suitable": true,
    });
    const [soilClimateLayers, setSoilClimateLayers] = useState({
        soilpH: false,
        organicMatter: false,
        rainfall: false,
        temperature: false,
        wind: false,
        sunshine: false,
    });
    const [geoJsonData, setGeoJsonData] = useState({ type: "FeatureCollection", features: [] });
    const [comparisonGeoJsonData, setComparisonGeoJsonData] = useState({ type: "FeatureCollection", features: [] });
    const [filters, setFilters] = useState({
        scenario: "",
        timeframe: "",
        season: "",
    });
    const [comparisonFilters, setComparisonFilters] = useState({
        scenario: "",
        timeframe: "",
        season: "",
    });
    const [isComparisonEnabled, setIsComparisonEnabled] = useState(false);
    const [isSideComparisonEnabled, setIsSideComparisonEnabled] = useState(false);
    const [selectedFeature, setSelectedFeature] = useState(null);

    const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

    const handleEnableComparison = () => {
        setIsComparisonEnabled((prev) => !prev);
        setIsSideComparisonEnabled(false); // Ensure side comparison is disabled
    };

    const handleSideEnableComparison = () => {
        setIsSideComparisonEnabled((prev) => !prev);
        setIsComparisonEnabled(false); // Ensure slider comparison is disabled
    };

    // Handler for feature click
    const handleFeatureClick = (feature) => {
        setSelectedFeature(feature);
    };

    // Handler to close popup
    const handleClosePopup = () => {
        setSelectedFeature(null);
    };

    useEffect(() => {
        const fetchData = async () => {
            try {
                const [suitabilityResponse, soilClimateResponse] = await Promise.all([
                    fetch("/api/suitability-data").catch(() => null),
                    fetch("/api/soilclimate-data").catch(() => null),
                ]);
                let suitabilityData = { features: [] };
                let soilClimateData = { features: [] };
                if(suitabilityResponse && suitabilityResponse.ok) {
                    try { suitabilityData = await suitabilityResponse.json(); } catch { suitabilityData = { features: [] }; }
                } else if (suitabilityResponse && suitabilityResponse.status === 404) {
                    if(process.env.NODE_ENV !== 'production') console.info('[SuitabilityMap] /api/suitability-data not present (skipping)');
                }
                if(soilClimateResponse && soilClimateResponse.ok) {
                    try { soilClimateData = await soilClimateResponse.json(); } catch { soilClimateData = { features: [] }; }
                } else if (soilClimateResponse && soilClimateResponse.status === 404) {
                    if(process.env.NODE_ENV !== 'production') console.info('[SuitabilityMap] /api/soilclimate-data not present (skipping)');
                }
                const allFeatures = [...suitabilityData.features, ...soilClimateData.features];

                // Filter data for the main map
                const newFilteredFeatures = allFeatures.filter((feature) => {
                    const matchesScenario = !filters.scenario || feature.properties.scenario === filters.scenario;
                    const matchesTimeframe = !filters.timeframe || feature.properties.timeframe === filters.timeframe;
                    const matchesSeason = !filters.season || feature.properties.season === filters.season;
                    const matchesCrop = !filters.crop || feature.properties.crop === filters.crop;

                    if (feature.properties.type === "suitability") {
                        return suitabilityLayers[feature.properties.suitability] && matchesScenario && matchesTimeframe && matchesSeason && matchesCrop;
                    } else if (feature.properties.type === "soilClimate") {
                        return soilClimateLayers[feature.properties.soilClimate] && matchesScenario && matchesTimeframe && matchesSeason && matchesCrop;
                    }
                    return false;
                });

                // Filter data for the comparison map
                const newComparisonFilteredFeatures = allFeatures.filter((feature) => {
                    const matchesScenario = !comparisonFilters.scenario || feature.properties.scenario === comparisonFilters.scenario;
                    const matchesTimeframe = !comparisonFilters.timeframe || feature.properties.timeframe === comparisonFilters.timeframe;
                    const matchesSeason = !comparisonFilters.season || feature.properties.season === comparisonFilters.season;
                    const matchesCrop = !filters.crop || feature.properties.crop === filters.crop;

                    if (feature.properties.type === "suitability") {
                        return suitabilityLayers[feature.properties.suitability] && matchesScenario && matchesTimeframe && matchesSeason && matchesCrop;
                    } else if (feature.properties.type === "soilClimate") {
                        return soilClimateLayers[feature.properties.soilClimate] && matchesScenario && matchesTimeframe && matchesSeason && matchesCrop;
                    }
                    return false;
                });

                setGeoJsonData({ type: "FeatureCollection", features: newFilteredFeatures });
                setComparisonGeoJsonData({ type: "FeatureCollection", features: newComparisonFilteredFeatures });
                setGeoJsonKey((prevKey) => prevKey + 1);
            } catch (error) {
                console.error("Error fetching data:", error);
            }
        };

        fetchData();
    }, [suitabilityLayers, soilClimateLayers, filters, comparisonFilters]);

    return (
        <div className="suitability-page resizable-container p-4 md:p-6 flex flex-col min-h-screen">
            <h1 className="text-2xl font-bold mb-4">Wheat Suitability Map</h1>
            <div className="flex justify-between items-center mb-4">
                <p className="text-lg mb-0">Explore the suitability of wheat production based on various environmental factors.</p>
            </div>

            <div className="map-sidebar flex flex-col md:flex-row gap-1 flex-1 relative">
                <div className="map-container absolute top-0 left-0 h-full w-full">
                    {/* Sidebar toggle button above the sidebar and map, always visible */}
                    <div className="absolute top-4 right-4 z-[2001]">
                        <button
                            className="map-burger-menu text-xl cursor-pointer bg-white bg-opacity-90 rounded-full p-2 shadow-md hover:bg-gray-100"
                            style={{ boxShadow: '0 2px 8px rgba(0,0,0,0.15)' }}
                            onClick={toggleSidebar}
                        >
                            <i className="fas fa-filter"></i>
                        </button>
                    </div>
                    {isSideComparisonEnabled ? (
                        <SidebysideComponent
                            geoJsonData={geoJsonData}
                            comparisonGeoJsonData={comparisonGeoJsonData}
                            geoJsonKey={geoJsonKey}
                            onFeatureClick={handleFeatureClick}
                        />
                    ) : isComparisonEnabled ? (
                        <SliderComponent
                            geoJsonData={geoJsonData}
                            comparisonGeoJsonData={comparisonGeoJsonData}
                            geoJsonKey={geoJsonKey}
                            onFeatureClick={handleFeatureClick}
                        />
                    ) : (
                        <MapComponent
                            geoJsonData={geoJsonData}
                            geoJsonKey={geoJsonKey}
                            onFeatureClick={handleFeatureClick}
                            toggleSidebar={toggleSidebar}
                        />
                    )}
                    {/* Popup */}
                    {selectedFeature && (
                        <div
                            className="suitability-detail-popup-overlay fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-30"
                            onClick={handleClosePopup}
                        >
                            <div
                            className="bg-white rounded-lg shadow-lg p-8"
                            onClick={e => e.stopPropagation()}
                            >
                            <SuitabilityDetailPopup feature={selectedFeature} onClose={handleClosePopup} />
                            </div>
                        </div>
                        )}
                </div>

                {isSidebarOpen && (
                    <div className="sidebar-container w-full md:w-[320px] bg-white shadow-lg rounded-md overflow-y-auto z-2000">
                        <SideBar
                            suitabilityLayers={suitabilityLayers}
                            setSuitabilityLayers={setSuitabilityLayers}
                            soilClimateLayers={soilClimateLayers}
                            setSoilClimateLayers={setSoilClimateLayers}
                            filters={filters}
                            setFilters={setFilters}
                            comparisonFilters={comparisonFilters}
                            setComparisonFilters={setComparisonFilters}
                            onEnableComparison={handleEnableComparison}
                            isComparisonEnabled={isComparisonEnabled}
                            onEnableSideComparison={handleSideEnableComparison}
                            isSideComparisonEnabled={isSideComparisonEnabled}
                            geoJsonData={geoJsonData}
                        />
                    </div>
                )}
            </div>
        </div>
    );
}

export default SuitabilityMap;
