import React, { useState, useCallback } from 'react';
import '../styles/Contact.css';

const phonenumber = "+251-912-345-678"; // Replace with your phone number

function Contact () {
  const [form, setForm] = useState({ first_name:'', last_name:'', email:'', phone_number:'', message:'' });
  const [status, setStatus] = useState({ submitting:false, success:null, error:null });
  const [touched, setTouched] = useState({});

  const apiBase = process.env.REACT_APP_API_BASE || '';
  const endpoint = `${apiBase}/api/contact/`; // Adjust if backend mounted differently

  const update = (e) => {
    const { name, value } = e.target;
    setForm(f => ({ ...f, [name]: value }));
  };
  const markTouched = (e) => setTouched(t => ({ ...t, [e.target.name]: true }));

  const validate = useCallback(() => {
    const errs = {};
    if(!form.first_name.trim()) errs.first_name = 'First name required';
    if(!form.last_name.trim()) errs.last_name = 'Last name required';
    if(!form.email.trim()) errs.email = 'Email required';
    else if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(form.email)) errs.email = 'Invalid email';
    if(!form.message.trim()) errs.message = 'Message required';
    if(form.phone_number && form.phone_number.length > 20) errs.phone_number = 'Phone too long';
    return errs;
  }, [form]);
  const errors = validate();

  const getCsrfToken = () => {
    const m = document.cookie.match(/csrftoken=([^;]+)/); return m ? m[1] : '';
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setTouched({ first_name:true, last_name:true, email:true, message:true, phone_number:true });
    if(Object.keys(errors).length) return;
    setStatus({ submitting:true, success:null, error:null });
    try {
      const resp = await fetch(endpoint, {
        method:'POST',
        headers: {
          'Content-Type':'application/json',
          'X-CSRFToken': getCsrfToken()
        },
        credentials:'include',
        body: JSON.stringify(form)
      });
      const contentType = resp.headers.get('content-type') || '';
      let payload = null;
      if(contentType.includes('application/json')) {
        try { payload = await resp.json(); } catch(_) { /* ignore */ }
      } else {
        // Fallback to text (e.g., HTML error page)
        try { const text = await resp.text(); payload = { raw: text.slice(0,500) }; } catch {}
      }
      if(!resp.ok) {
        const detail = payload?.errors ? JSON.stringify(payload.errors) : (payload?.message || 'Submission failed');
        throw new Error(detail);
      }
      setStatus({ submitting:false, success: payload?.message || 'Message sent successfully.', error:null });
      setForm({ first_name:'', last_name:'', email:'', phone_number:'', message:'' });
      setTouched({});
    } catch(err) {
      setStatus({ submitting:false, success:null, error: err.message });
    }
  };

  return (
    <div className="contact-container">
      <div className="content">
        <div className="info">
          <h1>Contact Us</h1>
          <p>Feel free to use the form or drop us an email. Old-fashioned phone calls work too.</p>
          <ul>
            <li><a href={`tel:${phonenumber}`} className="contact-link">{phonenumber}</a></li>
            <li><a className="contact-link" href='https://maps.app.goo.gl/Z3RVWMh8DkMSABHU8'>International Livestock Research Institute,<br />Addis Ababa</a></li>
          </ul>
        </div>
        <div className="form">
          <form onSubmit={handleSubmit} noValidate>
            <div className="name-fields">
              <div className="field">
                <label htmlFor="first_name">First Name</label>
                <div className='FLname'>
                  <input name="first_name" id="first_name" type="text" placeholder="First" value={form.first_name} onChange={update} onBlur={markTouched} aria-invalid={!!errors.first_name} />
                  {touched.first_name && errors.first_name && <span className="error-msg">{errors.first_name}</span>}
                </div>
              </div>
              <div className="field">
                <label htmlFor="last_name">Last Name</label>
                <div className='FLname'>
                  <input name="last_name" id="last_name" type="text" placeholder="Last" value={form.last_name} onChange={update} onBlur={markTouched} aria-invalid={!!errors.last_name} />
                  {touched.last_name && errors.last_name && <span className="error-msg">{errors.last_name}</span>}
                </div>
              </div>
            </div>
            <div className="field">
              <label htmlFor="email">Email</label>
              <input name="email" id="email" type="email" placeholder="example@email.com" value={form.email} onChange={update} onBlur={markTouched} aria-invalid={!!errors.email} />
              {touched.email && errors.email && <span className="error-msg">{errors.email}</span>}
            </div>
            <div className="field">
              <label htmlFor="phone_number">Phone (optional)</label>
              <input name="phone_number" id="phone_number" type="text" placeholder="xxx-xxx-xxxx" value={form.phone_number} onChange={update} onBlur={markTouched} aria-invalid={!!errors.phone_number} />
              {touched.phone_number && errors.phone_number && <span className="error-msg">{errors.phone_number}</span>}
            </div>
            <div className="field">
              <label htmlFor="message">Message</label>
              <textarea name="message" id="message" placeholder="Type your message ..." rows={5} value={form.message} onChange={update} onBlur={markTouched} aria-invalid={!!errors.message}></textarea>
              {touched.message && errors.message && <span className="error-msg">{errors.message}</span>}
            </div>
            {/* Honeypot anti-bot */}
            <div style={{ display:'none' }} aria-hidden="true">
              <input type="text" name="company" tabIndex={-1} autoComplete="off" onChange={()=>{}} />
            </div>
            <div className="submit">
              <button type="submit" disabled={status.submitting || Object.keys(errors).length>0}>
                {status.submitting ? 'Submitting…' : 'Submit'}
              </button>
            </div>
            <div role="status" className="form-status" aria-live="polite">
              {status.success && <p className="success-msg">{status.success}</p>}
              {status.error && <p className="error-msg">{status.error}</p>}
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Contact;