import React from 'react';

function DiseaseUpload() {
  const handleDiseaseSubmit = (event) => {
    event.preventDefault();
    const formData = new FormData(event.target);
    // In the future, you'll send this formData to your backend API
    console.log('Disease Form Data:', Object.fromEntries(formData));
    alert('Disease data submitted (frontend only)'); // Placeholder
  };

  // Enhanced design for better presentation
  return (
    <section className="disease-upload">
      <h2 className="disease-upload__title">Upload New Disease Information</h2>
      <form className="disease-upload__form" onSubmit={handleDiseaseSubmit}>
        <div className="form-group">
          <label htmlFor="disease_name">Disease Name:</label>
          <input type="text" id="disease_name" name="disease_name" required />
        </div>
        <div className="form-group">
          <label htmlFor="description">Description:</label>
          <textarea id="description" name="description" rows="5"></textarea>
        </div>
        <div className="form-group">
          <label htmlFor="suggestion">Suggestion:</label>
          <textarea id="suggestion" name="suggestion" rows="5"></textarea>
        </div>
        <div className="form-group">
          <label htmlFor="causes">Causes:</label>
          <textarea id="causes" name="causes" rows="5"></textarea>
        </div>
        <div className="form-group">
          <label htmlFor="treatment">Treatment Options:</label>
          <textarea id="treatment" name="treatment" rows="5"></textarea>
        </div>
        <div className="form-group">
          <label htmlFor="prevention">Prevention Methods:</label>
          <textarea id="prevention" name="prevention" rows="5"></textarea>
        </div>
        <div className="form-group">
          <label htmlFor="symptoms">Symptoms:</label>
          <textarea id="symptoms" name="symptoms" rows="5"></textarea>
        </div>
        <div className="form-group">
          <label htmlFor="affected_crops">Affected Crops:</label>
          <input type="text" id="affected_crops" name="affected_crops" />
        </div>
        <div className="form-group">
          <label htmlFor="disease_image">Disease Image/File:</label>
          <input type="file" id="disease_image" name="disease_image" />
        </div>
        <button className="btn btn-primary" type="submit">Save Disease Info</button>
      </form>
    </section>
  );
}

export default DiseaseUpload;