import React from 'react';
import { useNavigate } from 'react-router-dom';

function Logout() {
  const navigate = useNavigate();

  const handleLogout = () => {
    // Implement your actual logout logic here (e.g., clearing tokens, session)
    console.log('Logging out...');
    alert('Logged out!');
    navigate('/'); // Redirect to the homepage after logout
  };

  // Enhanced design for better presentation
  return (
    <section className="logout">
      <h2 className="logout__title">Logout</h2>
      <p className="logout__description">Are you sure you want to logout?</p>
      <button className="btn btn-danger" onClick={handleLogout}>Logout</button>
    </section>
  );
}

export default Logout;