import React from 'react';
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Layout from "../src/components/Layout/Layout.jsx";
import Home from "./pages/Home.jsx";
import About from "./pages/About.jsx";
import SuitabilityMap from "./pages/SuitabilityMap.jsx";
import RiskMap from "./pages/RiskMap.jsx";
import Advisory from "./pages/Advisory.jsx";
import Disease from "./pages/Disease.jsx";
import Contact from "./pages/Contact.jsx";
// import Admin from "./pages/Admin.jsx";
import Disclaimer from "./pages/Disclaimer.jsx";
import AdminPanel from "./components/Admin/AdminPanel.jsx";
import AdminDashboard from "./components/Admin/AdminDashboard.jsx";
import AdvisoryUpload from "./components/Admin/AdvisoryUpload.jsx";
import DiseaseUpload from "./components/Admin/DiseaseUpload.jsx";
import AdminSettings from "./components/Admin/AdminSettings.jsx";
import Logout from "./components/Admin/Logout.jsx";

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<Layout />}>
          <Route index element={<Home />} />
          <Route path="about" element={<About />} />
          <Route path="suitability-map" element={<SuitabilityMap />} />
          <Route path="risk-map" element={<RiskMap />} />
          <Route path="advisory" element={<Advisory />} />
          <Route path="disease" element={<Disease />} />
          <Route path="contact" element={<Contact />} />
          {/* <Route path="admin" element={<Admin />} /> */}
          <Route path="terms-and-conditions" element={<Disclaimer />} />
        </Route>
        <Route path="/admin/*" element={<AdminPanel />}>
          <Route index element={<AdminDashboard />} /> {/* Default route for /admin */}
          <Route path="dashboard" element={<AdminDashboard />} />
          <Route path="upload-advisory" element={<AdvisoryUpload />} />
          <Route path="upload-disease" element={<DiseaseUpload />} />
          <Route path="settings" element={<AdminSettings />} />
          <Route path="logout" element={<Logout />} />
        </Route>
      </Routes>
    </Router>
  );
}

export default App;