import React, { useRef, useEffect, useState } from "react";
import { MapContainer, TileLayer, LayersControl, GeoJSON } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import "../../styles/Sidebyside.css"; // Add custom CSS for resizable layout
import captureMapImage from "./captureMapImage"; // Import the capture function
import SuitabilityPopupHandler from "../Popups/suitabilityPopup"; // Import SuitabilityPopupHandler

function SidebysideComponent({ geoJsonData, comparisonGeoJsonData, geoJsonKey }) {
    const mapRef = useRef(null);
    const { BaseLayer } = LayersControl;
    const [dividerPosition, setDividerPosition] = useState(50);

    const handleMouseDown = (e) => {
        const startX = e.clientX;
        const startDividerPosition = dividerPosition;

        const handleMouseMove = (moveEvent) => {
            const deltaX = moveEvent.clientX - startX;
            const newDividerPosition = Math.min(
                90,
                Math.max(10, startDividerPosition + (deltaX / window.innerWidth) * 100)
            );
            setDividerPosition(newDividerPosition);
        };

        const handleMouseUp = () => {
            window.removeEventListener("mousemove", handleMouseMove);
            window.removeEventListener("mouseup", handleMouseUp);
        };

        window.addEventListener("mousemove", handleMouseMove);
        window.addEventListener("mouseup", handleMouseUp);
    };

    // Suitability legend classes and colors
    const suitabilityClasses = {
        "Highly Suitable": "#008000",
        "Moderately Suitable": "#FFFF00",
        "Marginally Suitable": "#FFA500",
        "Not Suitable": "#FF0000",
    };
    const [activeSuitabilityClasses, setActiveSuitabilityClasses] = useState(
        Object.keys(suitabilityClasses).reduce((acc, className) => {
            acc[className] = true;
            return acc;
        }, {})
    );

    // Legend click handler (same logic as Map.jsx)
    const handleLegendClick = (className, event) => {
        setActiveSuitabilityClasses(prevActiveClasses => {
            const currentStatusOfClicked = prevActiveClasses[className];
            const activeCount = Object.values(prevActiveClasses).filter(Boolean).length;
            const totalClasses = Object.keys(suitabilityClasses).length;
            if (!event.shiftKey) {
                // Normal click: Always toggles just that class ON/OFF
                return {
                    ...prevActiveClasses,
                    [className]: !currentStatusOfClicked
                };
            } else {
                // Shift+Click: smart behavior
                if (activeCount === totalClasses) {
                    // All ON: isolate
                    const newActiveClasses = {};
                    Object.keys(suitabilityClasses).forEach(key => {
                        newActiveClasses[key] = (key === className);
                    });
                    return newActiveClasses;
                } else if (activeCount === 1 && currentStatusOfClicked) {
                    // Only one ON: reset all
                    const newActiveClasses = {};
                    Object.keys(suitabilityClasses).forEach(key => {
                        newActiveClasses[key] = true;
                    });
                    return newActiveClasses;
                } else {
                    // Otherwise: toggle just that class
                    return {
                        ...prevActiveClasses,
                        [className]: !currentStatusOfClicked
                    };
                }
            }
        });
    };

    // Update getLayerStyle to use activeSuitabilityClasses
    const getLayerStyle = (feature) => {
        if (feature.properties.type === "suitability") {
            const suitability = feature.properties.suitability;
            const color = suitabilityClasses[suitability] || "#808080";
            if (!activeSuitabilityClasses[suitability]) {
                return { fillOpacity: 0, stroke: false };
            }
            return { color, fillColor: color, fillOpacity: 0.5 };
        } else if (feature.properties.type === "soilClimate") {
            switch (feature.properties.soilClimate) {
                case "soilpH":
                    return { color: "#0000FF", fillColor: "#0000FF", fillOpacity: 0.5 };
                case "organicMatter":
                    return { color: "#800080", fillColor: "#800080", fillOpacity: 0.5 };
                case "rainfall":
                    return { color: "#00FFFF", fillColor: "#00FFFF", fillOpacity: 0.5 };
                case "temperature":
                    return { color: "#008080", fillColor: "#008080", fillOpacity: 0.5 };
                case "wind":
                    return { color: "#A52A2A", fillColor: "#A52A2A", fillOpacity: 0.5 };
                case "sunshine":
                    return { color: "#000000", fillColor: "#000000", fillOpacity: 0.5 };
                default:
                    return { color: "#808080", fillColor: "#808080", fillOpacity: 0.5 };
            }
        }
        return { color: "#808080", fillColor: "#808080", fillOpacity: 0.5 };
    };

    // Filtered data for each map
    const filteredGeoJsonData = geoJsonData && geoJsonData.features.length > 0 ? {
        ...geoJsonData,
        features: geoJsonData.features.filter(feature =>
            feature.properties.type === "suitability"
                ? activeSuitabilityClasses[feature.properties.suitability]
                : true
        )
    } : geoJsonData;
    const filteredComparisonGeoJsonData = comparisonGeoJsonData && comparisonGeoJsonData.features.length > 0 ? {
        ...comparisonGeoJsonData,
        features: comparisonGeoJsonData.features.filter(feature =>
            feature.properties.type === "suitability"
                ? activeSuitabilityClasses[feature.properties.suitability]
                : true
        )
    } : comparisonGeoJsonData;

    useEffect(() => {
        if (mapRef.current) {
            mapRef.current.invalidateSize();
        }
    }, [geoJsonKey]);

    const onEachFeature = (feature, layer) => {
        // Use SuitabilityPopupHandler to handle popups
        SuitabilityPopupHandler({ feature ,layer, getLayerStyle});
    }

    return (
        <div className="resizable-container suitability-map">
            <di className="map-pane" style={{ width: `${dividerPosition}%` }}>
                <MapContainer
                    className="suitability-map w-full h-full rounded-lg border border-gray-300 z-0"
                    center={[9.03, 38.74]}
                    zoom={6}
                    whenCreated={(mapInstance) => {
                        mapRef.current = mapInstance;
                    }}
                >
                    <LayersControl position="topleft">
                        <BaseLayer checked name="OpenStreetMap">
                            <TileLayer
                                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                            />
                        </BaseLayer>
                    </LayersControl>

                    {filteredGeoJsonData && filteredGeoJsonData.features.length > 0 && (
                        <GeoJSON
                            key={`filtered-${geoJsonKey}-${JSON.stringify(activeSuitabilityClasses)}`}
                            data={filteredGeoJsonData}
                            style={getLayerStyle}
                            onEachFeature={onEachFeature}
                        />
                    )}
                </MapContainer>
            </di>
            <div className="divider" onMouseDown={handleMouseDown} />
            <div className="map-pane" style={{ width: `${100 - dividerPosition}%` }}>
                <MapContainer
                    className="suitability-map w-full h-full rounded-lg border border-gray-300 z-0"
                    center={[9.03, 38.74]}
                    zoom={6}
                    whenCreated={(mapInstance) => {
                        mapRef.current = mapInstance;
                    }}
                >
                    <LayersControl position="topleft">
                        <BaseLayer checked name="OpenStreetMap">
                            <TileLayer
                                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                            />
                        </BaseLayer>
                    </LayersControl>

                    {filteredComparisonGeoJsonData && filteredComparisonGeoJsonData.features.length > 0 && (
                        <GeoJSON
                            key={`filtered-comparison-${geoJsonKey}-${JSON.stringify(activeSuitabilityClasses)}`}
                            data={filteredComparisonGeoJsonData}
                            style={getLayerStyle}
                            onEachFeature={onEachFeature}
                        />
                    )}
                </MapContainer>
                <div
                id="map-legend"
                className="absolute bottom-1 left-1 z-[1000] p-3 bg-white rounded-md shadow-md"
            >
                <div className="flex flex-col gap-2">
                    <h4 className="text-gray-800 text-sm font-semibold mb-1">Suitability</h4>
                    {Object.entries(suitabilityClasses).map(([className, color]) => (
                        <div
                            key={className}
                            className={`flex items-center gap-2 cursor-pointer ${!activeSuitabilityClasses[className] ? 'line-through text-gray-400' : 'text-gray-700'}`}
                            onClick={event => handleLegendClick(className, event)}
                        >
                            <div
                                className="w-4 h-4 rounded-full border border-gray-300"
                                style={{ backgroundColor: color }}
                            ></div>
                            <span className="text-sm">{className}</span>
                        </div>
                    ))}
                </div>
            </div>
                <button
                onClick={captureMapImage}
                className="capture-button absolute bottom-4 right-4 bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-700 transition focus:outline-none shadow-md z-0"
                >
                Capture Map
            </button>
            </div>
        </div>
    );
}

export default SidebysideComponent;