// components/AdminPanel.js
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../../styles/Admin.css';
import Dashboard from './AdminDashboard';
import AdvisoryUpload from './AdvisoryUpload';
import DiseaseUpload from './DiseaseUpload';
import AdminSettings from './AdminSettings';
import Logout from './Logout';

function AdminPanel() {
  const navigate = useNavigate();
  const [activeSection, setActiveSection] = useState('dashboard');

  const handleNavigation = (path) => {
    navigate(`/admin${path}`);
    setActiveSection(path.substring(1));
  };

  // Enhanced design for better presentation
return (
    <div className="admin-container">
        <aside className="admin-sidebar">
            <div className="admin-logo">Admin Panel</div>
            <nav className="admin-navigation">
                <ul>
                    <li onClick={() => handleNavigation('/dashboard')} className={activeSection === 'dashboard' ? 'admin-navigation__item--active' : 'admin-navigation__item'}>Dashboard</li>
                    <li onClick={() => handleNavigation('/upload-advisory')} className={activeSection === 'upload-advisory' ? 'admin-navigation__item--active' : 'admin-navigation__item'}>Advisory Upload</li>
                    <li onClick={() => handleNavigation('/upload-disease')} className={activeSection === 'upload-disease' ? 'admin-navigation__item--active' : 'admin-navigation__item'}>Disease Upload</li>
                    <li onClick={() => handleNavigation('/settings')} className={activeSection === 'settings' ? 'admin-navigation__item--active' : 'admin-navigation__item'}>Settings</li>
                    <li onClick={() => handleNavigation('/logout')} className={activeSection === 'logout' ? 'admin-navigation__item--active' : 'admin-navigation__item'}>Logout</li>
                </ul>
            </nav>
        </aside>

        <main className="admin-content">
            <header className="admin-header">
                <h1 className="admin-header__title">{activeSection.replace(/-/g, ' ').replace(/([A-Z])/g, ' $1').trim().replace(/\b\w/g, char => char.toUpperCase()) || 'Admin Dashboard'}</h1>
                <div className="admin-header__user-info">Welcome, Admin</div>
            </header>

            <section className="admin-main">
                {/* Render active section content dynamically */}
                {activeSection === 'dashboard' && <Dashboard />}
                {activeSection === 'upload-advisory' && <AdvisoryUpload />}
                {activeSection === 'upload-disease' && <DiseaseUpload />}
                {activeSection === 'settings' && <AdminSettings />}
                {activeSection === 'logout' && <Logout />}
            </section>

            <footer className="admin-footer">
                <p>&copy; {new Date().getFullYear()} Admin Panel</p>
            </footer>
        </main>
    </div>
);
}

export default AdminPanel;