import React, { useEffect, useState } from "react";
import SubscribePopup from "../components/Popups/SubscribePopup";

function Advisory() {
  // State to hold the currently displayed advisory (single object)
  const [currentAdvisory, setCurrentAdvisory] = useState(null);
  // State to track the selected category, matching backend values
  const [selectedCategory, setSelectedCategory] = useState("Seasonal"); // Changed default to backend value
  const [isSubscribeVisible, setIsSubscribeVisible] = useState(false);

  useEffect(() => {
    const fetchAdvisoryByCategory = async (category) => {
      try {
        // Construct the URL with the category query parameter
        const response = await fetch(`http://localhost:3500/api/info_hub/advisories/recent_by_category/?category=${category}`);
        if (!response.ok) {
          if (response.status === 404) {
            console.log(`No recent advisory available for category: ${category}.`);
            setCurrentAdvisory(null); // Clear previous advisory if none found
            return;
          }
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setCurrentAdvisory(data); // Set the single advisory object
      } catch (error) {
        console.error("Error fetching advisory data by category:", error);
      }
    };

    // Fetch advisory for the initially selected category on mount
    fetchAdvisoryByCategory(selectedCategory);

    const timer = setTimeout(() => {
      setIsSubscribeVisible(true);
    }, 2000);

    return () => clearTimeout(timer);
  }, [selectedCategory]); // <--- IMPORTANT: Re-run useEffect when selectedCategory changes

  const handleCategoryChange = (category) => {
    setSelectedCategory(category);
    // The useEffect will automatically re-fetch because selectedCategory changed
  };

  const handleSubscribeClick = () => {
    setIsSubscribeVisible(true);
  };

  const handleClosePopup = () => {
    setIsSubscribeVisible(false);
  };

  const handleOverlayClick = (e) => {
    if (e.target.classList.contains("popup-overlay")) {
      setIsSubscribeVisible(false);
    }
  };

  const displayAdvisory = () => {
    // Check for currentAdvisory instead of advisoryData
    if (!currentAdvisory) return <p>No advisory found for the selected category.</p>;

    return (
      <div className="w-full md:w-3/4 border border-gray-300 p-4 rounded">
        {currentAdvisory.featured_image_file && (
          <img
            src={currentAdvisory.featured_image_file}
            alt="Featured"
            className="mb-4 max-h-64 object-contain rounded"
          />
        )}
        <p><strong>Title:</strong> {currentAdvisory.title}</p>
        <p><strong>Date posted:</strong> {currentAdvisory.published_date}</p>
        <p><strong>Advisory Content:</strong> {currentAdvisory.advisory_content}</p>
        <p><strong>Rainfall Forecast:</strong> {currentAdvisory.rainfall_forecast}</p>
        <p><strong>Temperature Outlook:</strong> {currentAdvisory.temperature_outlook}</p>
        <p><strong>Potential Risks:</strong> {currentAdvisory.potential_risks}</p>
        <p><strong>Suggestion:</strong> {currentAdvisory.suggestion}</p>
        <p><strong>Last Updated:</strong> {currentAdvisory.last_updated}</p>
      </div>
    );
  };

  return (
    <div className="flex flex-col items-center justify-center max-w-full mx-auto px-4 py-6 bg-white">
      <h1 className="text-3xl font-bold mb-6">Monthly and Seasonal Advisory</h1>

      <div className="flex flex-col md:flex-row max-w-[80%] w-full gap-6">
        <div className="w-full md:w-1/4 space-y-4">
          <button
            className={`w-full py-2 px-4 rounded text-white ${
              selectedCategory === "Seasonal" // Match backend value
                ? "bg-gray-800"
                : "bg-black"
            } hover:bg-gray-900`}
            onClick={() => handleCategoryChange("Seasonal")} // Pass backend value
          >
            Seasonal Advisory
          </button>
          <button
            className={`w-full py-2 px-4 rounded text-white ${
              selectedCategory === "Monthly" // Match backend value
                ? "bg-gray-800"
                : "bg-black"
            } hover:bg-gray-900`}
            onClick={() => handleCategoryChange("Monthly")} // Pass backend value
          >
            Monthly Advisory
          </button>
        </div>

        {displayAdvisory()}
      </div>

      <SubscribePopup
        isVisible={isSubscribeVisible}
        onClose={handleClosePopup}
        onOverlayClick={handleOverlayClick}
      />

      <button
        onClick={handleSubscribeClick}
        className="bg-yellow-400 text-white text-center py-4 px-6 mt-6 rounded-full w-full sm:w-1/2 hover:bg-yellow-500"
      >
        Subscribe to our Monthly and Seasonal Advisory{" "}
        <i className="fas fa-arrow-right ml-2"></i>
      </button>
    </div>
  );
}

export default Advisory;