import React from 'react';
function CardComponent({ title, text, buttonLink }) {
    return (
        <div className="home-card">
            <h2 className="home-card-title">{title}</h2>
            <p className="home-card-text">{text}</p>
            <button className="home-card-button" onClick={() => window.location.href = buttonLink}>
                Explore {title}
            </button>
        </div>
    );
}
export default CardComponent;