// ===============================================
// DEPRECATED LEAFLET IMPLEMENTATION
// This file now acts as a compatibility wrapper so that existing imports
// (e.g. import MapComponent from '../components/Data-Display/Map') keep working
// while we migrate to OpenLayers for GeoNode WMS integration.
// The previous, very large Leaflet-based code has been removed. If you still
// require specific UI pieces (search bar, suitability filters, downloads),
// re-implement them on top of the new OpenLayers stack or compose them here.
// ===============================================

import React, { useEffect } from 'react';
import GeoNodeWmsMap from '../OpenLayersMap/GeoNodeWmsMap';

/**
 * Wrapper MapComponent (deprecated API)
 * Props kept for backward compatibility but currently unused:
 *  - geoJsonData
 *  - geoJsonKey
 *  - onFeatureClick
 */
function MapComponent({ geoJsonData, geoJsonKey, onFeatureClick }) { // eslint-disable-line no-unused-vars
    useEffect(() => {
        if (process.env.NODE_ENV !== 'production') {
            // eslint-disable-next-line no-console
            console.warn('[MapComponent] Legacy Leaflet Map has been replaced by OpenLayers implementation.');
        }
    }, []);

    return (
        <div className="w-full h-full">
            <GeoNodeWmsMap layersEndpoint="/api/geonode/wms-layers" />
        </div>
    );
}

export default MapComponent;