import React, { useState, useEffect } from 'react';
// Remove the dummyData import:
// import dummyData from '../Data/dummyDiseasedata.json';
import DiseasePopup from '../components/Popups/DiseasePopup';

function DiseasePage() {
  const [diseases, setDiseases] = useState([]);
  const [filteredDiseases, setFilteredDiseases] = useState([]);
  const [popupData, setPopupData] = useState(null);
  const [selectedCrop, setSelectedCrop] = useState("");
  const [loading, setLoading] = useState(true); // Add loading state
  const [error, setError] = useState(null);   // Add error state

  useEffect(() => {
    const fetchDiseases = async () => {
      try {
        const response = await fetch('http://localhost:3500/api/info_hub/diseases/');
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setDiseases(data); // Set fetched data to diseases state
        setFilteredDiseases(data); // Initially, filtered is all diseases
        setLoading(false); // Data loaded, set loading to false
      } catch (e) {
        console.error("Error fetching disease data:", e);
        setError("Failed to load diseases. Please try again later."); // Set error message
        setLoading(false); // Stop loading even on error
      }
    };

    fetchDiseases();
  }, []); // Empty dependency array means this runs once on component mount

  const handleCropFilterChange = (event) => {
    const crop = event.target.value;
    setSelectedCrop(crop);

    if (crop === "") {
      setFilteredDiseases(diseases);
    } else {
      // The affected_crops field from Django is a single string "Wheat, Barley, Rye"
      // We need to split it and check if it includes the selected crop.
      const filtered = diseases.filter((disease) =>
        disease.affected_crops.split(', ').map(c => c.trim()).includes(crop)
      );
      setFilteredDiseases(filtered);
    }
  };

  const handleMoreClick = (disease) => {
    setPopupData(disease);
  };

  const closePopup = () => {
    setPopupData(null);
  };

  // Generate unique crops from the fetched data
  // Make sure to split the affected_crops string correctly
  const uniqueCrops = Array.from(
    new Set(diseases.flatMap((disease) => disease.affected_crops.split(', ').map(c => c.trim())))
  );

  // Add loading and error handling in the render
  if (loading) {
    return <div className="p-6 text-center">Loading diseases...</div>;
  }

  if (error) {
    return <div className="p-6 text-center text-red-600">{error}</div>;
  }

  // If no diseases are found after loading (e.g., API returned empty array)
  if (filteredDiseases.length === 0 && !selectedCrop) {
      return <div className="p-6 text-center">No diseases found.</div>;
  }
  if (filteredDiseases.length === 0 && selectedCrop) {
      return <div className="p-6 text-center">No diseases found for the selected crop "{selectedCrop}".</div>;
  }


  return (
    <div className="p-6">
      <h1 className="text-3xl font-bold mb-6 text-center">Crop Diseases</h1>

      <div className="text-left mb-6">
        <label htmlFor="crop-filter" className="block mb-2 font-medium">
          Filter by Affected Crop:
        </label>
        <select
          id="crop-filter"
          value={selectedCrop}
          onChange={handleCropFilterChange}
          className="border border-gray-300 rounded px-3 py-2 w-full max-w-xs focus:outline-none focus:ring focus:border-blue-400"
        >
          <option value="">All Crops</option>
          {uniqueCrops.map((crop) => (
            <option key={crop} value={crop}>
              {crop}
            </option>
          ))}
        </select>
      </div>

      <div className="grid gap-6 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
        {filteredDiseases.map((disease) => (
          <div
            key={disease.id}
            className="bg-white rounded-lg border border-gray-200 shadow-md p-4 hover:shadow-lg hover:scale-[1.03] transition-all"
          >
            <img
              src={disease.image} // Django returns the full URL directly
              alt={disease.name}
              className="w-full h-[150px] object-cover rounded mb-3"
            />
            <h2 className="text-lg font-semibold mb-2">{disease.name}</h2>
            {/* Displaying first 100 characters of description for preview */}
            <p className="text-sm text-gray-600 mb-3">{disease.description.substring(0, 100)}{disease.description.length > 100 ? '...' : ''}</p>
            <button
              onClick={() => handleMoreClick(disease)}
              className="text-green-700 hover:text-green-900 hover:underline font-semibold"
            >
              More
            </button>
          </div>
        ))}
      </div>

      {/* Pass disease.image and other relevant data to the popup */}
      <DiseasePopup popupData={popupData} closePopup={closePopup} />
    </div>
  );
}

export default DiseasePage;