// src/components/UI/SubscribePopup.jsx
import React from 'react';
import { Link } from 'react-router-dom'; // Import Link from react-router-dom

function SubscribePopup({ isVisible, onClose }) {
  if (!isVisible) {
    return null;
  }

  const handleSubmit = async (e) => {
    e.preventDefault();

    const firstName = document.getElementById("firstName").value;
    const lastName = document.getElementById("lastName").value;
    const email = document.getElementById("email").value;
    const termsAccepted = document.getElementById("terms").checked;

    if (!firstName || !lastName || !email || !termsAccepted) {
      alert("Please fill in all fields and accept the Disclaimer.");
      return;
    }

    const subscriptionData = {
      first_name: firstName, // Match backend model field name
      last_name: lastName,   // Match backend model field name
      email,
    };

    try {
      const response = await fetch("http://localhost:3500/api/subscribers/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(subscriptionData),
      });

      // Parse the response body first, as it might contain error messages
      const responseData = await response.json();

      if (!response.ok) {
        // Handle specific error messages from the backend
        if (response.status === 409) { // Conflict for duplicate email
          alert(responseData.detail || "This email is already subscribed.");
        } else if (response.status === 400) { // Bad Request for validation errors
          // Display specific validation errors from the backend
          let errorMessages = "";
          for (const key in responseData) {
            errorMessages += `${key}: ${responseData[key].join(", ")}\n`;
          }
          alert(`Validation Error:\n${errorMessages}`);
        } else {
          // Generic error for other HTTP errors
          throw new Error(responseData.message || "Failed to subscribe. Please try again later.");
        }
        return; // Stop execution after handling the error
      }

      // Successful response
      alert(responseData.message || "Subscription successful! Thank you for subscribing.");
      onClose(); // Close the popup after successful subscription
    } catch (error) {
      console.error("Error subscribing:", error);
      alert("An error occurred. Please try again later.");
    }
  };

  return (
    <div className="fixed top-0 left-0 w-full h-full bg-black bg-opacity-50 flex justify-center items-center z-50" onClick={onClose}>
      <div className="relative bg-sub-pop-light-yellow p-8 rounded-lg shadow-xl w-11/12 md:w-[450px] text-center font-sans" onClick={(e) => e.stopPropagation()}>
        <h2 className="text-2xl font-bold mb-5 text-gray-800">Subscribe</h2>
        <p className="text-lg text-gray-700 mb-6 leading-relaxed">
          Subscribe for Free Stay informed with timely Agro-climate
          updates and expert farming advice to your email.
        </p>
        <form onSubmit={handleSubmit} className="text-left">
          <div className="mb-4">
            <label htmlFor="firstName" className="block text-gray-700 text-sm font-bold mb-2">First Name</label>
            <input type="text" id="firstName" name="firstName" className="shadow appearance-none border-b-2 border-gray-300 rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:border-orange-500 bg-transparent" />
          </div>
          <div className="mb-4">
            <label htmlFor="lastName" className="block text-gray-700 text-sm font-bold mb-2">Last Name</label>
            <input type="text" id="lastName" name="lastName" className="shadow appearance-none border-b-2 border-gray-300 rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:border-orange-500 bg-transparent" />
          </div>
          <div className="mb-4">
            <label htmlFor="email" className="block text-gray-700 text-sm font-bold mb-2">Email</label>
            <input type="email" id="email" name="email" className="shadow appearance-none border-b-2 border-gray-300 rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:border-orange-500 bg-transparent" />
          </div>
          <div className="mb-6 flex items-center">
            <input type="checkbox" id="terms" name="terms" className="mr-2 form-checkbox h-5 w-5 text-orange-500 focus:ring-orange-500 border-gray-300 rounded" />
            <label htmlFor="terms" className="text-gray-700 text-sm font-normal">I have read and accepted the <Link to="/terms-and-conditions" className="text-black hover:underline">Disclaimer</Link></label>
          </div>
          <button className="bg-yellow-400 hover:bg-yellow-500 text-white font-bold py-3 px-6 rounded focus:outline-none focus:shadow-outline flex items-center justify-center w-full gap-2" type="submit">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" fill="currentColor" className="bi bi-envelope-fill" viewBox="0 0 16 16">
              <path d="M.05 3.555A2 2 0 0 1 2 2h12a2 2 0 0 1 1.95 1.555L8 8.414l-7.95-4.859ZM0 4.697v7.104l5.803-3.558L0 4.697ZM6.761 8.83l-6.57 4.027A2 2 0 0 0 2 14h12a2 2 0 0 0 1.808-1.144l-6.57-4.027L8 9.586l-1.239-.757Zm3.436-.586L16 11.801V4.697l-5.803 3.558Z"/>
            </svg>
            Subscribe
          </button>
        </form>
        <button className="absolute top-2 right-2 text-gray-500 hover:text-gray-700 text-xl font-bold outline-none" onClick={onClose}>
          Close
        </button>
      </div>
    </div>
  );
}

export default SubscribePopup;