// Helper utilities to build and execute WMS GetFeatureInfo requests for OpenLayers
// Assumes GeoServer WMS 1.3.0; adjust crs/srs rules if 1.1.1 needed.

import { getWidth, getHeight } from 'ol/extent';

/**
 * buildGetFeatureInfoUrl
 * Generates a WMS GetFeatureInfo URL for the given map click.
 * @param {Object} opts
 * @param {string} opts.baseUrl Base WMS endpoint (e.g., https://geonode.example.org/geoserver/wms)
 * @param {string} opts.layer Published layer name (workspace:layer)
 * @param {Array<number>} opts.coordinate Map coordinate in map projection
 * @param {import('ol/Map').default} opts.map OL Map instance
 * @param {string} [opts.infoFormat] Desired MIME type (e.g. application/json, text/html)
 * @returns {string|null}
 */
export function buildGetFeatureInfoUrl({ baseUrl, layer, coordinate, map, infoFormat='application/json', version='1.3.0' }) {
  if(!baseUrl || !layer || !map) return null;
  const view = map.getView();
  const projection = view.getProjection();
  const resolution = view.getResolution();
  const extent = view.calculateExtent(map.getSize());
  const width = Math.round(getWidth(extent) / resolution);
  const height = Math.round(getHeight(extent) / resolution);
  const bboxParam = extent.join(',');
  const pixel = map.getPixelFromCoordinate(coordinate);
  const col = Math.round(pixel[0]);
  const row = Math.round(pixel[1]);

  const is130 = version === '1.3.0';
  const params = new URLSearchParams({
    SERVICE: 'WMS',
    VERSION: version,
    REQUEST: 'GetFeatureInfo',
    LAYERS: layer,
    QUERY_LAYERS: layer,
    INFO_FORMAT: infoFormat,
    FEATURE_COUNT: '10'
  });
  if(is130) {
    params.set('CRS', projection.getCode());
    params.set('BBOX', bboxParam);
    params.set('WIDTH', width.toString());
    params.set('HEIGHT', height.toString());
    params.set('I', col.toString());
    params.set('J', row.toString());
  } else {
    // 1.1.1 variant
    params.set('SRS', projection.getCode());
    params.set('BBOX', bboxParam);
    params.set('WIDTH', width.toString());
    params.set('HEIGHT', height.toString());
    params.set('X', col.toString());
    params.set('Y', row.toString());
  }
  return `${baseUrl}?${params.toString()}`;
}

/**
 * Build a set of candidate URLs (versions & formats) to probe when initial request returns empty.
 */
export function buildGetFeatureInfoCandidates({ baseUrl, layer, coordinate, map, formats=['application/json','text/plain'], versions=['1.3.0','1.1.1'] }) {
  const result = [];
  versions.forEach(v => {
    formats.forEach(fmt => {
      const url = buildGetFeatureInfoUrl({ baseUrl, layer, coordinate, map, infoFormat: fmt, version: v });
      if(url) result.push({ url, version: v, format: fmt });
    });
  });
  return result;
}

/**
 * fetchFeatureInfo
 * Fetches and returns JSON (or text) from GetFeatureInfo URL.
 */
export async function fetchFeatureInfo(url) {
  const resp = await fetch(url, { credentials: 'include' });
  if(!resp.ok) throw new Error(`GetFeatureInfo HTTP ${resp.status}`);
  const contentType = resp.headers.get('content-type') || '';
  if(contentType.includes('application/json')) return resp.json();
  return resp.text();
}

/**
 * Try multiple candidate URLs until one returns data (non-empty for JSON, non-empty string for text) or all fail.
 */
export async function tryGetFeatureInfoSequence(candidates) {
  const errors = [];
  for(const c of candidates) {
    try {
      const data = await fetchFeatureInfo(c.url);
      if(typeof data === 'string') {
        if(data.trim().length) return { data, meta: c };
      } else if(data && (data.features ? data.features.length > 0 : Object.keys(data).length > 0)) {
        return { data, meta: c };
      } else {
        // keep trying if empty
        errors.push(`Empty response for ${c.version} ${c.format}`);
      }
    } catch(e) {
      errors.push(`${c.version} ${c.format}: ${e.message}`);
    }
  }
  throw new Error(errors.join(' | '));
}
