import { useMap } from "react-leaflet";
import { useEffect } from "react";
import L from "leaflet";
import "leaflet-easyprint";

function PrintControl() {
    const map = useMap();

    useEffect(() => {
        if (!map) return;

        // Use hidden: true so no button is rendered, and expose the printPlugin instance
        const printPlugin = L.easyPrint({
            title: 'Download Map Image',
            position: 'topright',
            sizeModes: ['Current'],
            exportOnly: true,
            filename: 'map_capture',
            hidden: true, // Do not render any UI button
        }).addTo(map);

        // Attach to map for programmatic access
        map.easyPrintPlugin = printPlugin;

        return () => {
            printPlugin.remove();
            delete map.easyPrintPlugin;
        };
    }, [map]);

    return null;
}
export default PrintControl;
