import React from "react";
import { MapContainer, TileLayer, Marker, Popup, GeoJSON } from "react-leaflet";

const RegionInfoSection = ({ regionName, properties, geometry, bounds, mapCenter, zoomLevel }) => (
  <div className="flex flex-col md:flex-row md:space-x-6 max-w-xl mx-auto">
    <section className="md:w-1/3 space-y-3 mb-6 md:mb-0">
      <p className="text-sm font-semibold">
        <span className="font-bold">Region:</span> {regionName}
      </p>
      <p className="text-sm font-semibold">
        <span className="font-bold">Suitability:</span> {properties.suitability || "N/A"}
      </p>
      <p className="text-sm font-semibold">
        <span className="font-bold">Scenario:</span> {properties.scenario || "N/A"}
      </p>
      <p className="text-sm font-semibold">
        <span className="font-bold">Timeframe:</span> {properties.timeframe || "N/A"}
      </p>
      <p className="text-sm font-semibold">
        <span className="font-bold">Season:</span> {properties.season || "N/A"}
      </p>
      <p className="text-sm font-semibold">
        <span className="font-bold">Crop:</span> {properties.crop || "N/A"}
      </p>
      <p className="text-sm font-semibold">
        <span className="font-bold">Description:</span> {properties.description || "N/A"}
      </p>
    </section>
    <section className="md:w-2/3 border border-gray-300 rounded overflow-hidden">
      <div className="h-[300px] w-full" aria-label={`Map of ${regionName} area with location markers and zoom controls`} id="region-map">
        <MapContainer
          {...(bounds && bounds.length > 1 ? { bounds } : { center: mapCenter, zoom: zoomLevel })}
          style={{ height: "100%", width: "100%" }}
        >
          <TileLayer
            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />
          {geometry && (geometry.type === "Polygon" || geometry.type === "MultiPolygon") && (
            <GeoJSON data={{ type: "Feature", geometry, properties: {} }} style={{ color: "#0074D9", weight: 2, fillOpacity: 0.2 }} />
          )}
          <Marker position={mapCenter}>
            <Popup>{regionName}</Popup>
          </Marker>
        </MapContainer>
      </div>
    </section>
  </div>
);

export default RegionInfoSection;