// src/pages/RiskMap.jsx

import React, { useEffect, useState } from "react";
import RiskSidebar from "../components/UI/RiskSidebar"; // Make sure path is correct
import RiskMapComponent from "../components/Data-Display/riskmapcomponent"; // Make sure path is correct
import SliderComponent from "../components/Data-Display/sliderpage"; // Assuming this is still used
import SidebysideComponent from "../components/Data-Display/Sidebyside"; // Assuming this is still used
// import RiskDetailPopup from "../components/Popups/RiskDetailPopup"; // Make sure path is correct

import dummyRiskData from "../Data/dummyRiskData.json"; // Your dummy data source

import "../styles/RiskMap.css"; // Ensure this path is correct for your project

function RiskMap() {
    const [isSidebarOpen, setIsSidebarOpen] = useState(() => window.innerWidth > 768);
    const [geoJsonKey, setGeoJsonKey] = useState(0); // Key to force GeoJSON re-render

    // State for filtering dummyRiskData based on risk types
    const [riskTypes, setRiskTypes] = useState({
        drought: true,
        pests: true,
        soilDegradation: true,
        extremeWeather: true,
    });

    // State for additional filters (region, severity, crop)
    const [filters, setFilters] = useState({
        region: "",
        severity: "",
        crop: ""
    });

    const [filteredData, setFilteredData] = useState(dummyRiskData); // The data passed to the map

    // Comparison Mode States (from your earlier requirements)
    const [isComparisonEnabled, setIsComparisonEnabled] = useState(false);
    const [isSideComparisonEnabled, setIsSideComparisonEnabled] = useState(false);
    const [comparisonFilters, setComparisonFilters] = useState({ // For slider/side-by-side
        scenario: "",
        timeframe: "",
        eventType: "",
    });
    // For simplicity, comparison will use the same dummyRiskData.json structure,
    // but filtered by comparisonFilters.
    const [comparisonGeoJsonData, setComparisonGeoJsonData] = useState({ type: "FeatureCollection", features: [] });


    // Popup state
    const [selectedFeature, setSelectedFeature] = useState(null);

    const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

    // Handlers for comparison modes
    const handleEnableComparison = () => {
        setIsComparisonEnabled((prev) => !prev);
        setIsSideComparisonEnabled(false); // Disable side-by-side if slider is enabled
    };

    const handleSideEnableComparison = () => {
        setIsSideComparisonEnabled((prev) => !prev);
        setIsComparisonEnabled(false); // Disable slider if side-by-side is enabled
    };

    const handleFeatureClick = (feature) => {
        setSelectedFeature(feature);
    };

    const handleClosePopup = () => {
        setSelectedFeature(null);
    };

    // Effect to filter dummyRiskData based on riskTypes and filters
    useEffect(() => {
        const applyFilters = () => {
            // Define anyRiskTypeSelected BEFORE using it in both filter calls
            const anyRiskTypeSelected = Object.values(riskTypes).some(Boolean);

            const newFilteredFeatures = dummyRiskData.features.filter((feature) => {
                const props = feature.properties;
                const matchesRegion = !filters.region || props.region === filters.region;
                const matchesSeverity = !filters.severity || props.severity === filters.severity;
                const matchesCrop = !filters.crop || props.crop === filters.crop;

                // Check if any active risk type matches a non-null/non-low value in properties
                const matchesDrought = riskTypes.drought && props.drought_impact && props.drought_impact !== "Low";
                const matchesPests = riskTypes.pests && props.pests_present && props.pests_present !== "No";
                const matchesSoil = riskTypes.soilDegradation && props.soil_degradation_level && props.soil_degradation_level !== "Low";
                const matchesExtreme = riskTypes.extremeWeather && props.extreme_weather_risk && props.extreme_weather_risk !== "Low";

                // If no risk type is selected in the sidebar, show all features related to risk properties.
                // Otherwise, show only features matching at least one selected risk type.
                const matchesAnyRiskType = anyRiskTypeSelected ? (matchesDrought || matchesPests || matchesSoil || matchesExtreme) : true;

                return matchesRegion && matchesSeverity && matchesCrop && matchesAnyRiskType;
            });
            setFilteredData({
                type: "FeatureCollection",
                features: newFilteredFeatures,
            });

            // For comparison map (if using a different filtering logic for it)
            // For now, let's assume it also filters dummyRiskData.json but with its own comparisonFilters
            const newComparisonFilteredFeatures = dummyRiskData.features.filter((feature) => {
                const props = feature.properties;
                const matchesScenario = !comparisonFilters.scenario || props.scenario === comparisonFilters.scenario;
                const matchesTimeframe = !comparisonFilters.timeframe || props.timeframe === comparisonFilters.timeframe;
                const matchesEventType = !comparisonFilters.eventType || props.eventType === comparisonFilters.eventType;
                // Assuming comparison also considers dummy risk types if relevant
                const matchesDroughtComp = riskTypes.drought && props.drought_impact && props.drought_impact !== "Low";
                const matchesPestsComp = riskTypes.pests && props.pests_present && props.pests_present !== "No";
                const matchesSoilComp = riskTypes.soilDegradation && props.soil_degradation_level && props.soil_degradation_level !== "Low";
                const matchesExtremeComp = riskTypes.extremeWeather && props.extreme_weather_risk && props.extreme_weather_risk !== "Low";
                const matchesAnyRiskTypeComp = anyRiskTypeSelected ? (matchesDroughtComp || matchesPestsComp || matchesSoilComp || matchesExtremeComp) : true; // Use the same anyRiskTypeSelected

                return matchesScenario && matchesTimeframe && matchesEventType && matchesAnyRiskTypeComp;
            });
            setComparisonGeoJsonData({ type: "FeatureCollection", features: newComparisonFilteredFeatures });

            setGeoJsonKey((prevKey) => prevKey + 1); // Force map re-render
        };

        applyFilters();
    }, [riskTypes, filters, comparisonFilters]);


    return (
        <div className="Risk-page p-4 md:p-6 flex flex-col min-h-screen">
            <div className="flex justify-between items-center mb-4">
                <div>
                    <h1 className="text-2xl font-bold mb-2">Climate Risk Map</h1>
                    <p className="text-lg mb-0">
                        Identify potential risks to wheat production in Ethiopia.
                    </p>
                </div>
            </div>

            <div className="map-sidebar flex flex-col md:flex-row gap-4 flex-1 relative">
                {/* Burger menu for sidebar on small screens */}
                <div className="absolute top-4 right-4 z-[2001]">
                    <button
                        className="map-burger-menu text-xl cursor-pointer bg-white bg-opacity-90 rounded-full p-2 shadow-md hover:bg-gray-100"
                        style={{ boxShadow: '0 2px 8px rgba(0,0,0,0.15)' }}
                        onClick={toggleSidebar}
                    >
                        <i className="fas fa-filter"></i> {/* Assuming FontAwesome for icon */}
                    </button>
                </div>

                {/* Map Container - Conditionally render based on comparison mode */}
                <div className={`map-container flex-1 border border-gray-300 rounded-md min-h-[500px] relative transition-width duration-300 ease-in-out ${
                    isSidebarOpen ? "md:w-[calc(100%-320px)]" : "w-full"
                }`}>
                    {isSideComparisonEnabled ? (
                        <SidebysideComponent
                            geoJsonData={filteredData}
                            comparisonGeoJsonData={comparisonGeoJsonData}
                            geoJsonKey={geoJsonKey}
                            onFeatureClick={handleFeatureClick}
                        />
                    ) : isComparisonEnabled ? (
                        <SliderComponent
                            geoJsonData={filteredData}
                            comparisonGeoJsonData={comparisonGeoJsonData}
                            geoJsonKey={geoJsonKey}
                            onFeatureClick={handleFeatureClick}
                        />
                    ) : (
                        // Standard Risk Map Component
                        <RiskMapComponent
                            geoJsonData={filteredData} // Pass the filtered dummy data
                            geoJsonKey={geoJsonKey}
                            onFeatureClick={handleFeatureClick}
                            // No need to pass toggleSidebar, riskTypes, setRiskTypes to map component for direct control of sidebar/filters
                            // Map component will not directly manipulate sidebar or overall riskType/filter states
                        />
                    )}
                </div>

                {/* Risk Detail Popup (managed at page level) */}
                {/* {selectedFeature && (
                    <div
                        className="suitability-detail-popup-overlay fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-30"
                        onClick={handleClosePopup}
                    >
                        <div
                            className="bg-white rounded-lg shadow-lg p-8"
                            onClick={e => e.stopPropagation()}
                        >
                            <RiskDetailPopup feature={selectedFeature} onClose={handleClosePopup} />
                        </div>
                    </div>
                )} */}


                {/* Sidebar Component */}
                {isSidebarOpen && (
                    <div className="risk-sidebar-container w-full md:w-[320px] bg-white rounded-md overflow-y-auto z-20 shadow-lg">
                        <RiskSidebar
                            riskTypes={riskTypes}
                            setRiskTypes={setRiskTypes}
                            filters={filters}
                            setFilters={setFilters}
                            // Pass comparison related props if the sidebar controls them
                            comparisonFilters={comparisonFilters}
                            setComparisonFilters={setComparisonFilters}
                            onEnableComparison={handleEnableComparison}
                            isComparisonEnabled={isComparisonEnabled}
                            onEnableSideComparison={handleSideEnableComparison}
                            isSideComparisonEnabled={isSideComparisonEnabled}
                            riskData={dummyRiskData} // Sidebar can access all dummy data for dropdowns
                        />
                    </div>
                )}
            </div>
        </div>
    );
}

export default RiskMap;