import React from 'react';

// Simple layer switcher dropdown; expects array of layer meta objects.
export default function LayerSwitcher({ layers, activeLayer, onChange }) {
  if(!layers || !layers.length) return null;
  return (
    <div className="absolute top-2 left-2 z-20 bg-white bg-opacity-95 shadow rounded p-2 text-sm space-y-1 w-56">
      <label className="block text-gray-600 text-xs font-semibold tracking-wide">Layer</label>
      <select
        className="w-full border border-gray-300 rounded px-2 py-1 text-sm focus:outline-none focus:ring focus:border-blue-400"
        value={activeLayer?.id || ''}
        onChange={e => onChange(e.target.value)}
      >
        {layers.map(l => (
          <option key={l.id} value={l.id}>{l.title || l.layer_name}</option>
        ))}
      </select>
    </div>
  );
}
