import React, { useEffect, useState, useMemo } from 'react';
import FeatureInfoPanel from './FeatureInfoPanel';
import { toLonLat } from 'ol/proj';
import BiomassTrendSection from '../Popups/BiomassTrendSection';
import BiomassForecastSection from '../Popups/BiomassForecastSection';
import RegionInfoSection from '../Popups/RegionInfoSection';

/**
 * WmsDataPopup
 * Shows enriched information for a clicked WMS raster pixel.
 * Combines raw GetFeatureInfo response with optional time‑series & forecast endpoints.
 *
 * Props:
 *  - featureInfo: { raw, coordinate, meta }
 *  - layer: active layer metadata (id,title,layer_name)
 *  - onClose: function
 */
export default function WmsDataPopup({ featureInfo, layer, onClose }) {
  const [activeTab, setActiveTab] = useState('info');
  const [trend, setTrend] = useState(null); // { labels:[], datasets:[{data:[]}] }
  const [forecast, setForecast] = useState(null);
  const [regionMeta, setRegionMeta] = useState(null); // { regionName, properties, geometry, bounds, mapCenter, zoomLevel }
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const apiBase = process.env.REACT_APP_DATA_API_BASE || '';

  // Derive simple key/value pairs from featureInfo raw for quick view
  const rawAttributes = useMemo(() => {
    if(!featureInfo?.raw) return {};
    const r = featureInfo.raw;
    if(r.features && r.features.length) return r.features[0].properties || {}; // first feature
    if(typeof r === 'object' && !Array.isArray(r)) return r; // generic object
    return { value: typeof r === 'string' ? r.substring(0,400) : JSON.stringify(r).substring(0,400) };
  }, [featureInfo]);

  useEffect(() => {
    if(!featureInfo || !layer) return;
    let abort = false;
    const load = async () => {
      setLoading(true); setError(null);
      try {
        const [trendRes, forecastRes] = await Promise.all([
          fetchTimeSeries(apiBase, layer, featureInfo).catch(() => null),
          fetchForecast(apiBase, layer, featureInfo).catch(() => null)
        ]);
        if(abort) return;
        setTrend(trendRes);
        setForecast(forecastRes);
        const regionRes = await fetchRegionMeta(apiBase, featureInfo).catch(() => null);
        if(abort) return;
        setRegionMeta(regionRes);
      } catch(e) {
        if(!abort) setError(e.message || 'Failed loading extra data');
      } finally { if(!abort) setLoading(false); }
    };
    load();
    return () => { abort = true; };
  }, [featureInfo, layer, apiBase]);

  const lonLat = useMemo(() => {
    if(!featureInfo?.coordinate) return null;
    try { return toLonLat(featureInfo.coordinate); } catch { return featureInfo.coordinate; }
  }, [featureInfo]);

  const tabs = [
    { id: 'info', label: 'Info' },
    { id: 'trend', label: 'Trend', disabled: !trend },
    { id: 'forecast', label: 'Forecast', disabled: !forecast },
    { id: 'region', label: 'Region', disabled: !regionMeta }
  ];

  return (
    <div className="wms-data-popup flex flex-col max-h-[70vh]">
      <header className="flex items-center justify-between mb-2">
        <h3 className="text-sm font-semibold text-gray-700 truncate pr-2">{layer?.title || layer?.layer_name}</h3>
        <button onClick={onClose} className="text-gray-500 hover:text-gray-800 text-lg leading-none">×</button>
      </header>
      <nav className="flex gap-1 mb-2 flex-wrap">
        {tabs.map(t => (
          <button key={t.id} disabled={t.disabled}
            onClick={() => setActiveTab(t.id)}
            className={`px-2 py-1 text-xs rounded border ${activeTab===t.id ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-gray-700 border-gray-300'} ${t.disabled ? 'opacity-40 cursor-not-allowed' : 'hover:bg-blue-50'}`}>{t.label}</button>
        ))}
      </nav>
      <div className="overflow-auto custom-scrollbar pr-1">
        {activeTab === 'info' && (
          <div className="space-y-2">
            {loading && <div className="text-xs text-gray-500">Loading extra data…</div>}
            {error && <div className="text-xs text-red-600">{error}</div>}
            <AttributeTable attributes={rawAttributes} meta={featureInfo?.meta} lonLat={lonLat} />
          </div>
        )}
        {activeTab === 'trend' && trend && (
          <BiomassTrendSection biomassTrendData={trend.data} biomassTrendOptions={trend.options} />
        )}
        {activeTab === 'forecast' && forecast && (
          <BiomassForecastSection biomassForecastData={forecast.data} biomassForecastOptions={forecast.options} />
        )}
        {activeTab === 'region' && regionMeta && (
          <RegionInfoSection {...regionMeta} />
        )}
      </div>
    </div>
  );
}

function AttributeTable({ attributes, meta, lonLat }) {
  const entries = Object.entries(attributes || {});
  const copyFirst = () => {
    const first = entries[0];
    if(!first) return;
    const val = first[1];
    const txt = `${first[0]}=${val}${lonLat?` @ ${lonLat[0].toFixed(5)},${lonLat[1].toFixed(5)}`:''}`;
    navigator.clipboard?.writeText(txt).catch(()=>{});
  };
  return (
    <div className="border border-gray-200 rounded p-2 bg-white shadow-sm">
      <h4 className="text-xs font-semibold text-gray-600 mb-1">Pixel / Feature Attributes</h4>
      {meta && <p className="text-[10px] text-gray-400 mb-1">Source: {meta.version} {meta.format}</p>}
      {lonLat && <p className="text-[10px] text-gray-400 mb-1">Lon/Lat: {lonLat[0].toFixed(5)}, {lonLat[1].toFixed(5)} <button onClick={copyFirst} className="ml-2 text-blue-600 underline">Copy</button></p>}
      {entries.length === 0 && <div className="text-xs text-gray-500">No attributes.</div>}
      <table className="w-full text-[11px]">
        <tbody>
          {entries.map(([k,v]) => (
            <tr key={k} className="align-top">
              <td className="pr-2 text-gray-500 whitespace-nowrap">{k}</td>
              <td className="text-gray-800 break-all">{formatValue(v)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function formatValue(v){
  if(v === null || v === undefined) return '';
  if(typeof v === 'number') return v.toLocaleString();
  return String(v);
}

// -------- Data fetch helpers (stubs / example). Replace endpoints as needed. --------
async function fetchTimeSeries(apiBase, layer, featureInfo){
  // Example endpoint: /api/time-series?layer=<>&lon=&lat=
  const [lon, lat] = invertCoordinates(featureInfo.coordinate);
  const url = `${apiBase}/api/time-series?layer=${encodeURIComponent(layer.layer_name)}&lon=${lon}&lat=${lat}`;
  try {
    const r = await fetch(url);
    if(!r.ok) throw new Error('ts status '+r.status);
    const json = await r.json();
    if(!json.labels || !json.values) return null;
    return {
      data: {
        labels: json.labels,
        datasets: [{ label: json.label || 'Value', data: json.values, borderColor: '#2563eb', tension: 0.2, fill:false }]
      },
      options: { responsive: true, maintainAspectRatio: false, scales: { x: { ticks:{ maxTicksLimit:8 } } } }
    };
  } catch { return null; }
}
async function fetchForecast(apiBase, layer, featureInfo){
  const [lon, lat] = invertCoordinates(featureInfo.coordinate);
  const url = `${apiBase}/api/forecast?layer=${encodeURIComponent(layer.layer_name)}&lon=${lon}&lat=${lat}`;
  try {
    const r = await fetch(url);
    if(!r.ok) throw new Error('fc status '+r.status);
    const json = await r.json();
    if(!json.labels || !json.values) return null;
    return {
      data: { labels: json.labels, datasets: [{ label: json.label || 'Forecast', data: json.values, borderColor: '#b45309', tension:0.2 }] },
      options: { responsive:true, maintainAspectRatio:false }
    };
  } catch { return null; }
}
async function fetchRegionMeta(apiBase, featureInfo){
  // Example reverse lookup endpoint (optional)
  const [lon, lat] = invertCoordinates(featureInfo.coordinate);
  const url = `${apiBase}/api/region-info?lon=${lon}&lat=${lat}`;
  try {
    const r = await fetch(url);
    if(!r.ok) throw new Error('region status '+r.status);
    const json = await r.json();
    // Expect { name, properties, geometry }
    if(!json.name) return null;
    return {
      regionName: json.name,
      properties: json.properties || {},
      geometry: json.geometry || null,
      bounds: json.bounds || null,
      mapCenter: json.center || [lat, lon],
      zoomLevel: json.zoom || 8
    };
  } catch { return null; }
}

function invertCoordinates(coord){
  try { return toLonLat(coord); } catch { return coord; }
}
