import React, { useEffect, useRef, useState, useCallback } from 'react';
import Map from 'ol/Map';
import View from 'ol/View';
import TileLayer from 'ol/layer/Tile';
import {fromLonLat} from 'ol/proj';
import TileWMS from 'ol/source/TileWMS';
import {defaults as defaultControls, Attribution, ScaleLine, Zoom} from 'ol/control';
import Overlay from 'ol/Overlay';
import 'ol/ol.css';
import './map.css';
import { buildGetFeatureInfoUrl, fetchFeatureInfo, buildGetFeatureInfoCandidates, tryGetFeatureInfoSequence } from './getFeatureInfo';
import LayerSwitcher from './LayerSwitcher';
// import FeatureInfoPanel from './FeatureInfoPanel'; // replaced by richer popup
import WmsDataPopup from './WmsDataPopup';

/**
 * GeoNodeWmsMap
 * Props:
 *  - layersEndpoint: string (API endpoint in your backend that returns an array of {id, title, wms_url, layer_name})
 *  - initialLayerId?: string (optional layer id to load first)
 *  - center?: [lon, lat]
 *  - zoom?: number
 */
export default function GeoNodeWmsMap({ layersEndpoint=process.env.REACT_APP_WMS_LAYERS_ENDPOINT || '/api/geonode/wms-layers', initialLayerId, center=[38.74,9.03], zoom=6 }) {
  const mapDivRef = useRef(null);
  const popupContainerRef = useRef(null);
  const popupCloserRef = useRef(null);
  const mapRef = useRef(null);
  const [layersMeta, setLayersMeta] = useState([]);
  const [activeLayerMeta, setActiveLayerMeta] = useState(null);
  const [featureInfo, setFeatureInfo] = useState(null); // Stores last GetFeatureInfo result
  const [loadingInfo, setLoadingInfo] = useState(false);
  const [errorInfo, setErrorInfo] = useState(null);
  const overlayRef = useRef(null);
  // Mount debug (helps verify the live bundle includes latest code)
  useEffect(() => {
    console.log('[GeoNodeWmsMap] mounted at', new Date().toISOString(), 'endpoint=', layersEndpoint);
  }, [layersEndpoint]);

  // Parse capabilities XML into a simple layer list (workspace:layer name)
  const parseCapabilities = useCallback((xmlText, capabilitiesUrl) => {
    try {
      const doc = new window.DOMParser().parseFromString(xmlText, 'text/xml');
      const root = doc.querySelector('Capability > Layer');
      if(!root) return [];
      const base = capabilitiesUrl.split('?')[0];
      const layers = [];
      root.querySelectorAll(':scope > Layer').forEach(le => {
        const name = le.querySelector('Name')?.textContent?.trim();
        if(!name) return;
        const title = le.querySelector('Title')?.textContent?.trim() || name;
        layers.push({ id: name, title, layer_name: name, wms_url: base });
      });
      return layers;
    } catch(err){
      if(process.env.NODE_ENV !== 'production') console.error('Capabilities parse error', err);
      return [];
    }
  }, []);

  // Fetch layer list (supports JSON or direct capabilities XML URL)
  useEffect(() => {
    let ignore = false;
    const load = async () => {
      try {
        const resp = await fetch(layersEndpoint);
        if(!resp.ok) throw new Error('Failed fetching layers endpoint: '+resp.status);
        const ct = resp.headers.get('content-type') || '';
        let list = [];
        if(ct.includes('application/json')) {
          list = await resp.json();
        } else {
          const txt = await resp.text();
          if(/<WMS_Capabilities|<WMT_MS_Capabilities/i.test(txt)) list = parseCapabilities(txt, layersEndpoint); else throw new Error('Unsupported layersEndpoint format');
        }
        if(ignore) return;
        setLayersMeta(list);
        if(list.length) {
          const first = initialLayerId ? list.find(l => l.id === initialLayerId) : list[0];
          setActiveLayerMeta(first);
        }
      } catch(err){
        console.error(err);
      }
    };
    load();
    return () => { ignore = true; };
  }, [layersEndpoint, initialLayerId, parseCapabilities]);

  // Initialize map once
  useEffect(() => {
    if(!mapDivRef.current || mapRef.current) return;

    const map = new Map({
      target: mapDivRef.current,
      view: new View({
        center: fromLonLat(center),
        zoom,
      }),
      controls: defaultControls({ attribution: false }).extend([
        new Attribution({ collapsible: true }),
        new Zoom(),
        new ScaleLine(),
      ]),
      layers: []
    });
    mapRef.current = map;
  // Expose for manual debugging in browser console
  if(typeof window !== 'undefined') window.__geonodeMap = map;

    // Popup overlay
    overlayRef.current = new Overlay({
      element: popupContainerRef.current,
      autoPan: { animation: { duration: 250 } },
      positioning: 'bottom-center',
      stopEvent: true,
    });
    map.addOverlay(overlayRef.current);

    return () => map.setTarget(undefined);
  }, [center, zoom]);

  // Build and add (or replace) the active WMS layer
  useEffect(() => {
    if(!activeLayerMeta || !mapRef.current) return;

    // Remove existing WMS layers (keep controls/overlays)
    const map = mapRef.current;
    map.getLayers().forEach(l => {
      if(l.get('isWmsLayer')) map.removeLayer(l);
    });

  const { wms_url: metaUrl, layer_name } = activeLayerMeta;
  const overrideBase = process.env.REACT_APP_GEOSERVER_WMS_URL;
  const wms_url = overrideBase ? overrideBase : metaUrl;
    const wmsSource = new TileWMS({
      url: wms_url,
      params: {
        LAYERS: layer_name, // Use GeoServer published name
        TILED: true,
        VERSION: '1.3.0',
      },
      transition: 0,
      crossOrigin: 'anonymous'
    });
    const wmsLayer = new TileLayer({ source: wmsSource });
    wmsLayer.set('isWmsLayer', true);
    map.addLayer(wmsLayer);
  }, [activeLayerMeta]);

  // Handle map click -> GetFeatureInfo
  useEffect(() => {
    const map = mapRef.current;
    if(!map) return;

    const handleClick = async (evt) => {
      console.log('[GeoNodeWmsMap] singleclick', evt.coordinate, 'activeLayer=', activeLayerMeta?.layer_name);
      if(!activeLayerMeta) return;
      const { wms_url: metaUrl, layer_name } = activeLayerMeta;
      const overrideBase = process.env.REACT_APP_GEOSERVER_WMS_URL;
      const wms_url = overrideBase ? overrideBase : metaUrl;
      setLoadingInfo(true);
      setErrorInfo(null);
      setFeatureInfo(null);
      try {
        const primaryUrl = buildGetFeatureInfoUrl({ baseUrl: wms_url, layer: layer_name, coordinate: evt.coordinate, map, infoFormat: 'application/json', version: '1.3.0' });
        if(primaryUrl) console.log('[GeoNodeWmsMap] primary GFI URL', primaryUrl);
        let data = null; let meta = { format: 'application/json', version: '1.3.0', url: primaryUrl }; let success = false;
        if(primaryUrl){
          try {
            data = await fetchFeatureInfo(primaryUrl);
            if(typeof window !== 'undefined') window.__lastGfiUrl = primaryUrl;
            if(data && (data.features ? data.features.length : Object.keys(data).length)) success = true;
          } catch {/* fall back */}
        }
        if(!success){
          const candidates = buildGetFeatureInfoCandidates({ baseUrl: wms_url, layer: layer_name, coordinate: evt.coordinate, map });
          const res = await tryGetFeatureInfoSequence(candidates);
          data = res.data; meta = res.meta;
          if(typeof window !== 'undefined') window.__lastGfiUrl = meta.url;
          console.log('[GeoNodeWmsMap] fallback GFI success', meta);
        }
        setFeatureInfo({ coordinate: evt.coordinate, raw: data, meta });
        overlayRef.current.setPosition(evt.coordinate);
      } catch(e){
        if(process.env.NODE_ENV !== 'production') console.error('GetFeatureInfo error', e);
        setErrorInfo(e.message || 'GetFeatureInfo failed');
      } finally { setLoadingInfo(false); }
    };
    map.on('singleclick', handleClick);
    return () => map.un('singleclick', handleClick);
  }, [activeLayerMeta]);

  const closePopup = useCallback(() => {
    setFeatureInfo(null);
    if(overlayRef.current) overlayRef.current.setPosition(undefined);
  }, []);

  const handleLayerChange = (layerId) => {
    const found = layersMeta.find(l => l.id === layerId);
    if(found) {
      setActiveLayerMeta(found);
      closePopup();
    }
  };

  return (
    <div className="ol-map-wrapper relative w-full h-full">
      {/* Layer Switcher */}
      <LayerSwitcher layers={layersMeta} activeLayer={activeLayerMeta} onChange={handleLayerChange} />

      {/* Map Container */}
      <div ref={mapDivRef} className="ol-map w-full h-full rounded shadow" />

      {/* Popup Overlay (mobile friendly) */}
      <div ref={popupContainerRef} className={`ol-popup ${featureInfo ? 'visible' : ''}`}>
        <button ref={popupCloserRef} onClick={closePopup} className="ol-popup-closer">×</button>
        <WmsDataPopup featureInfo={featureInfo} layer={activeLayerMeta} onClose={closePopup} loading={loadingInfo} error={errorInfo} />
      </div>
    </div>
  );
}
