import React from 'react';
import '../../styles/Diseasepopup.css'; // Import your CSS file for styling

function DiseasePopup({ popupData, closePopup }) {
    if (!popupData) return null;

    return (
        <div className="popup-overlay" onClick={closePopup}>
            <div className="popup-content" onClick={(e) => e.stopPropagation()}>
                <button className="close-popup-button" onClick={closePopup}>X</button>
                <h2>{popupData.name}</h2>
                <img src={popupData.image} alt={popupData.name} className="w-full h-auto max-h-80 object-contain mx-auto mb-4 rounded" />
                <div className='popup-info'>
                    <p><strong>Description:</strong> {popupData.description}</p>
                    {/* Handle null suggestion gracefully */}
                    <p><strong>Causes:</strong> {popupData.causes}</p>
                    {/* Corrected field names to match API */}
                    <p><strong>Treatment Options:</strong> {popupData.treatment_options}</p>
                    <p><strong>Prevention Methods:</strong> {popupData.prevention_methods}</p>
                    {/* Display symptoms as a string, no join needed */}
                    <p><strong>Symptoms:</strong> {popupData.symptoms}</p>
                    {/* Display affected_crops as a string, no join needed */}
                    <p><strong>Affected Crops:</strong> {popupData.affected_crops}</p>
                </div>
            </div>
        </div>
    );
};

export default DiseasePopup;